// ─────────────────────────────────────────────────────────────────────────────
// App state: profile, YOUR ratings, Browse Mode sessions and walkthrough progress.
// Persisted to localStorage under KEY. Simulated community data is NOT stored here;
// it is generated by services/community.js.
//
// Saved shape (v2):
//   user            profile (see data/user.js)
//   ratings         [{ articleId, points, submittedAt (ISO) }]   — final once submitted
//   browseSessions  [{ day: 'YYYY-MM-DD', enteredAt: ms }]        — one per local day at most
//   journey         walkthrough flags
// The old v1 data (four-level ratings with written explanations) is ignored, not migrated.
// ─────────────────────────────────────────────────────────────────────────────
import { createContext, useCallback, useContext, useEffect, useMemo, useReducer, useRef, useState } from 'react';
import { defaultUser } from '../data/user.js';
import { getArticle } from '../data/articles.js';
import { isValidPoints } from '../data/ratingScale.js';
import * as clock from '../lib/clock.js';
import { boundaries } from '../lib/schedule.js';
import { visibilityFor } from '../lib/visibility.js';
import { modeFor, ratedTodayCount, canEnterBrowse as canEnterBrowseFn, MIN_DAILY_RATINGS } from '../lib/modes.js';
import { userAlignment } from '../lib/alignment.js';

const KEY = 'media-lens:v2';
const JOURNEY = { searched: false, rated: false, ratedThree: false, compared: false, sources: false, browsed: false, profileViewed: false };
const fresh = () => ({ user: { ...defaultUser, joined: new Date(clock.now()).toISOString().slice(0, 10) }, ratings: [], browseSessions: [], journey: { ...JOURNEY } });

function load() {
  try {
    const raw = localStorage.getItem(KEY);
    if (!raw) return fresh();
    const s = JSON.parse(raw);
    const base = fresh();
    return {
      user: { ...base.user, ...s.user, demographics: { ...base.user.demographics, ...(s.user?.demographics || {}) } },
      ratings: Array.isArray(s.ratings) ? s.ratings.filter((r) => getArticle(r.articleId) && isValidPoints(r.points)) : [],
      browseSessions: Array.isArray(s.browseSessions) ? s.browseSessions : [],
      journey: { ...JOURNEY, ...s.journey },
    };
  } catch { return fresh(); }
}

function reducer(state, action) {
  switch (action.type) {
    case 'rate':
      if (state.ratings.some((r) => r.articleId === action.rating.articleId)) return state; // ratings are final
      return { ...state, ratings: [action.rating, ...state.ratings] };
    case 'enterBrowse':
      if (state.browseSessions.some((s) => s.day === action.session.day)) return state;
      return { ...state, browseSessions: [...state.browseSessions, action.session], journey: { ...state.journey, browsed: true } };
    case 'updateUser':
      return { ...state, user: { ...state.user, ...action.patch, demographics: { ...state.user.demographics, ...(action.patch.demographics || {}) } } };
    case 'journey':
      return state.journey[action.step] ? state : { ...state, journey: { ...state.journey, [action.step]: true } };
    case 'resetActivity':
      return { ...state, ratings: [], browseSessions: [], journey: { ...JOURNEY } };
    case 'resetAll':
      return fresh();
    default:
      return state;
  }
}

/** Re-render on every window boundary, at local midnight, on demo-clock changes, and every 15 s. */
function useAppNow() {
  const [t, setT] = useState(clock.now);
  useEffect(() => {
    const keyAt = (x) => `${boundaries().filter((b) => b <= x).length}|${clock.localDayKey(x)}`;
    let lastKey = keyAt(clock.now()), lastSet = Date.now();
    const id = setInterval(() => {
      const x = clock.now(), k = keyAt(x);
      if (k !== lastKey || Date.now() - lastSet > 15000) { lastKey = k; lastSet = Date.now(); setT(x); }
    }, 1000);
    const unsub = clock.subscribe(() => { const x = clock.now(); lastKey = keyAt(x); lastSet = Date.now(); setT(x); });
    return () => { clearInterval(id); unsub(); };
  }, []);
  return t;
}

const Ctx = createContext(null);

export function StoreProvider({ children }) {
  const [state, dispatch] = useReducer(reducer, undefined, load);
  const [toasts, setToasts] = useState([]);
  const tid = useRef(0);
  const now = useAppNow();

  useEffect(() => { try { localStorage.setItem(KEY, JSON.stringify(state)); } catch { /* storage unavailable */ } }, [state]);

  const toast = useCallback((msg, tone = 'default') => {
    const id = ++tid.current;
    setToasts((t) => [...t, { id, msg, tone }]);
    setTimeout(() => setToasts((t) => t.filter((x) => x.id !== id)), 4200);
  }, []);

  const ratingMap = useMemo(() => new Map(state.ratings.map((r) => [r.articleId, r])), [state.ratings]);
  const ratingFor = useCallback((id) => ratingMap.get(id) || null, [ratingMap]);
  const mode = modeFor(state.browseSessions, now);
  const viewer = useMemo(() => ({ now, mode, ratingFor, browseSessions: state.browseSessions }), [now, mode, ratingFor, state.browseSessions]);
  const vis = useCallback((article) => visibilityFor(article, viewer), [viewer]);
  const ratedToday = ratedTodayCount(state.ratings, now);

  // Alignment only changes when ratings change or an article closes.
  const closedKey = boundaries().filter((b) => b <= now).length;
  // eslint-disable-next-line react-hooks/exhaustive-deps
  const alignment = useMemo(() => userAlignment(state.ratings, now), [state.ratings, closedKey]);

  const markJourney = useCallback((step) => dispatch({ type: 'journey', step }), []);

  /** Submit a rating. Re-checks eligibility against the clock at the moment of submission. */
  const submitRating = useCallback((articleId, points) => {
    const article = getArticle(articleId);
    const t = clock.now();
    const v = article && visibilityFor(article, { ...viewer, now: t, mode: modeFor(state.browseSessions, t) });
    if (!article || !isValidPoints(points)) return { ok: false, error: 'That rating is not valid.' };
    if (!v.canRate) {
      const msg = { closed: 'This article closed to new ratings before you submitted.', rated: 'You have already rated this article.', browse: 'Ratings are paused while you are in Browse Mode.', 'seen-in-browse': 'You saw live results for this article in Browse Mode, so it can’t be rated.', upcoming: 'This article is not published yet.' }[v.reason];
      toast(msg, 'error');
      return { ok: false, error: msg };
    }
    const rating = { articleId, points, submittedAt: new Date(t).toISOString() };
    dispatch({ type: 'rate', rating });
    clock.notify(); // refresh the app time so the new rating is counted immediately
    dispatch({ type: 'journey', step: 'rated' });
    if (ratedTodayCount([rating, ...state.ratings], t) >= MIN_DAILY_RATINGS) dispatch({ type: 'journey', step: 'ratedThree' });
    return { ok: true, rating };
  }, [viewer, state.browseSessions, state.ratings, toast]);

  const enterBrowse = useCallback(() => {
    const t = clock.now();
    if (!canEnterBrowseFn(state.ratings, state.browseSessions, t)) return false;
    dispatch({ type: 'enterBrowse', session: { day: clock.localDayKey(t), enteredAt: t } });
    toast('Browse Mode on. Rating resumes tomorrow.', 'success');
    return true;
  }, [state.ratings, state.browseSessions, toast]);

  const demo = useMemo(() => ({
    advance: (ms) => clock.advance(ms),
    restart: () => { clock.restartTimeline(); dispatch({ type: 'resetActivity' }); },
    offset: clock.getOffset(),
    epoch: clock.getEpoch(),
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }), [now]);

  const value = useMemo(() => ({
    ...state, now, boundaryKey: closedKey, mode, viewer, vis, ratingFor, ratedToday,
    canEnterBrowse: canEnterBrowseFn(state.ratings, state.browseSessions, now),
    alignment, toasts, toast, dispatch, submitRating, enterBrowse, markJourney, demo,
  }), [state, now, closedKey, mode, viewer, vis, ratingFor, ratedToday, alignment, toasts, toast, submitRating, enterBrowse, markJourney, demo]);

  return <Ctx.Provider value={value}>{children}</Ctx.Provider>;
}

export const useStore = () => useContext(Ctx);
